{
  "cards": {
    "cover": {
      "narration": "Chiang Mai, 5–8 Jan 2027, 4 days and 3 of the Night Market Crew. Shoes off, phone down, eyes up—mostly.",
      "headline": "Chiang Mai"
    },
    "critters": {
      "narration": "3 forms found, 2 brand-new locals met. The undergrowth did not disappoint."
    },
    "route": {
      "narration": "Old City, Doi Suthep, Nimman: about 73 km of wandering, 3 stops and an 05:30 pre-sunrise on day 3.",
      "line": "Longest leg was Old City to Doi Suthep, 15.2 km in 30 minutes; no driver on record, so the crew steered themselves."
    },
    "awards": {
      "narration": "Three travellers, three awards. No trophies, just the right names for the right habits."
    },
    "receipt": {
      "narration": "THB 28,400 across 31 expenses and 17 meals, settled 1 day after the trip. THB 9,467 each, and no plan was set to argue with.",
      "line": "Shoes off, accounts settled, trip stamped."
    },
    "stamp": {
      "narration": "4 days, 3 travellers, 1 permanent page. The Night Market Crew stamps Chiang Mai and signs it with dust from Doi Suthep."
    },
    "postcard": {
      "narration": "The long way home starts here, but first, one more night market lap.",
      "line": "Chiang Mai was loud, hot and full of tiny new friends. Save us a seat at the next night market."
    }
  },
  "awards": [
    {
      "user_id": "0199a0f2-0000-7000-8000-000000000001",
      "title": "Earliest riser",
      "line": "1 early start, up at 05:30, out of 2 crew early starts."
    },
    {
      "user_id": "0199a0f2-0000-7000-8000-000000000002",
      "title": "Treasurer",
      "line": "Logged 20 of 31 expenses, 65 percent of the paper trail."
    },
    {
      "user_id": "0199a0f2-0000-7000-8000-000000000003",
      "title": "Explorer",
      "line": "Visited 9 of 14 places, 64 percent of the crew map."
    }
  ]
}
